/// Performs a lower‐bound (first index where `a[idx] >= x`) search
/// in the half‐open interval [lo, hi) of the slice `a`.
///
/// Precondition: `a.len() >= hi`.
/// Returns `k` in `lo..=hi` such that:
///   for all r in lo..k,     a[r] < x,
///   for all r in k..hi,     a[r] >= x.
pub fn search_range_helper(a: &[i32], x: i32, lo: usize, hi: usize) -> usize {
    let mut lo = lo;
    let mut hi = hi;
    // Invariant: we are searching in [lo, hi]
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if a[mid] < x {
            // answer must be to the right of mid
            lo = mid + 1;
        } else {
            // answer is at mid or to the left of mid
            hi = mid;
        }
    }
    lo
}

/// Computes the insertion position (lower‐bound) of `x`
/// in the first 1000 elements of `a`.  Assumes `a.len() >= 1000`
/// and that `a[0..1000]` is sorted in nondecreasing order.
///
/// Returns `k` in `0..=1000` such that:
///   for all  r in 0..k,       a[r] <  x,
///   for all  r in k..1000,    a[r] >= x.
pub fn search_1000(a: &[i32], x: i32) -> usize {
    // If you want, you can uncomment the following check in debug mode:
    // debug_assert!(a.len() >= 1000, "slice must have at least 1000 elements");
    search_range_helper(a, x, 0, 1000)
}

